{"implementation": "import math
def solve(case):
    matrix = case.get('matrix')
    idf = case.get('idf')
    vector = case.get('vector')
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise ValueError('matrix must be a list of lists')
    n_rows = len(matrix)
    if n_rows == 0:
        raise ValueError('matrix must have at least one row')
    n_cols = len(matrix[0])
    if not all(len(row) == n_cols for row in matrix):
        raise ValueError('rows must have same length')
    if not isinstance(idf, list) or len(idf) != n_cols:
        raise ValueError('idf must be a list of length n_cols')
    if not isinstance(vector, list) or len(vector) != n_rows:
        raise ValueError('vector must be a list of length n_rows')
    eps = 1e-12
    scaled = []
    for row in matrix:
        new_row = [row[j] * idf[j] for j in range(n_cols)]
        scaled.append(new_row)
    degrees = []
    for row in scaled:
        deg = sum(c*c for c in row)
        if deg < eps:
            deg = eps
        degrees.append(deg)
    Dinv_sqrt = [1.0 / math.sqrt(d) for d in degrees]
    v_scaled = [vector[i] * Dinv_sqrt[i] for i in range(n_rows)]
    y = [0.0] * n_cols
    for j in range(n_cols):
        s = 0.0
        for i in range(n_rows):
            s += scaled[i][j] * v_scaled[i]
        y[j] = s
    v2 = [0.0] * n_rows
    for i in range(n_rows):
        s = 0.0
        for j in range(n_cols):
            s += scaled[i][j] * y[j]
        v2[i] = s
    result = [v2[i] * Dinv_sqrt[i] for i in range(n_rows)]
    round_result = [round(x, 6) for x in result]
    round_degrees = [round(d, 6) for d in degrees]
    return {'operator_result': round_result, 'degrees': round_degrees}"}
